123	        if (owners.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
132	        Owner owner = this.clinicService.findOwnerById(ownerId);
133	        if (owner == null) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
142	        HttpHeaders headers = new HttpHeaders();
143	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
144	        normalizeOwnerFields(owner);
145	        // Enforce the pre-persistence policies that can reject the new owner outright.
146	        rejectDisallowedOwnerCreation(owner);
147	        // Resolve the owner's household membership: assign the shared 'householdId' when the
148	        // request opts in and joins an existing household, and record the household size. This runs
149	        // before the identity-key check so that check sees the owner's final household id.
150	        applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
151	        // Reject the create when the owner's whole derived identity key (normalized telephone,
152	        // email and household id) already matches an existing owner. This single rule subsumes the
153	        // former separate telephone, email and household duplicate checks.
154	        rejectWhenIdentityInUse(owner);
155	        // Assign the remaining create-time derived fields (namesake count, customer code,
156	        // membership number and bulk-signup warning), each fixed at creation time.
157	        assignDerivedFields(owner);
158	        this.clinicService.saveOwner(owner);
159	        // Emit an audit line for the successful create, carrying the owner id, customer code and
160	        // registration date so the create can be traced from the dedicated AUDIT log.
161	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
162	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
163	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
164	        headers.setLocation(UriComponentsBuilder.newInstance()
165	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
166	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
167	    }
168	
169	    /**
170	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
171	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
172	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
173	     * the sequence of create-time rejections stays readable and a new rule is added as one more
174	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
175	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
176	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
177	     * the household id has been resolved, because that key includes the household id.
178	     *
179	     * @param owner the newly mapped and normalized owner being created
180	     */
181	    private void rejectDisallowedOwnerCreation(Owner owner) {
182	        rejectWhenDailyLimitReached(owner);
183	        rejectWhenCityAtCapacity(owner);
184	    }
185	
186	    /**
187	     * Applies the household-membership rules for a newly normalized owner being created. It finds
188	     * the existing owners who share the owner's household (same last name and address, compared
189	     * case-insensitively with collapsed whitespace), then, using that single lookup: when the
190	     * request opts in via {@code sharesHousehold} and the owner joins an existing household, assigns
191	     * the new owner and every existing member the same stable {@code householdId}; and records the
192	     * owner's {@code householdSize}. Sharing a household is no longer a rejection on its own: a new
193	     * owner is rejected only when its whole identity key matches an existing owner (see
194	     * {@link #rejectWhenIdentityInUse}), and the household id resolved here is part of that key.
195	     *
196	     * @param owner           the newly mapped and normalized owner being created
197	     * @param sharesHousehold whether the request opted in to joining an existing household
198	     */
199	    private void applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
200	        // Identify any existing owners who share a household (same last name and address,
201	        // compared case-insensitively with collapsed whitespace) with the owner being created.
202	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
203	        // When opting in and joining an existing household, assign the new owner and every
204	        // existing member the same stable household identifier derived from the last name and
205	        // address, so all owners of the household share one 'householdId'.
206	        if (sharesHousehold && !householdMembers.isEmpty()) {
207	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
208	            owner.setHouseholdId(householdId);
209	            for (Owner member : householdMembers) {
210	                if (!householdId.equals(member.getHouseholdId())) {
211	                    member.setHouseholdId(householdId);
212	                    this.clinicService.saveOwner(member);
213	                }
214	            }
215	        }
216	        // Record the size of this owner's household after this create, i.e. the number of owners
217	        // sharing this owner's 'householdId' once it is persisted. An owner that shares an existing
218	        // household counts the matched members plus itself; an owner without a shared household is a
219	        // household of one. Fixed at creation time.
220	        owner.setHouseholdSize(owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1);
221	    }
222	
223	    /**
224	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
225	     * has already been resolved: the namesake count, the per-city customer code, the membership
226	     * number derived from that customer code and the registration year, and the bulk-signup warning
227	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
228	     * here keeps {@link #addOwner} focused on the high-level create sequence.
229	     *
230	     * @param owner the owner being created, already normalized and with its household resolved
231	     */
232	    private void assignDerivedFields(Owner owner) {
233	        // Record how many existing owners already share this owner's first and last name
234	        // (compared case-insensitively) before this create, fixed at creation time.
235	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
236	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
237	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
238	        // time.
239	        owner.setCustomerCode(customerCode(owner));
240	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
241	        // of the registration date's year (e.g. 'NSW-A1B2C3D4-M26'), fixed at creation time.
242	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
243	        // Flag the create when more than 80 owners have already been created on this owner's
244	        // (adjusted business-day) registration date, fixed at creation time.
245	        owner.setBulkSignupWarning(
246	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
247	    }
248	
249	    /**
250	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
251	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
252	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
253	     * the former separate telephone, email and household duplicate checks: two owners collide only
254	     * when their whole keys are equal, and members of one household with different telephones have
255	     * different keys and are both allowed.
256	     *
257	     * @param owner the owner being created, already normalized and with its household resolved
258	     */
259	    private void rejectWhenIdentityInUse(Owner owner) {
260	        String identityKey = owner.getIdentityKey();
261	        boolean inUse = this.clinicService.findAllOwners().stream()
262	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
263	        if (inUse) {
264	            throw new DuplicateIdentityException(
265	                "An owner with identity key " + identityKey + " already exists");
266	        }
267	    }
268	
269	    /**
270	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
271	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
272	     *
273	     * @param owner the owner being created
274	     */
275	    private void rejectWhenDailyLimitReached(Owner owner) {
276	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
277	            throw new DailyOwnerLimitExceededException(
278	                "The maximum number of owners that may be created today has already been reached");
279	        }
280	    }
281	
282	    /**
283	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
284	     * or more owners, with 409 Conflict.
285	     *
286	     * @param owner the owner being created
287	     */
288	    private void rejectWhenCityAtCapacity(Owner owner) {
289	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
290	            throw new CityCapacityExceededException(
291	                "The city " + owner.getCity() + " already contains the maximum number of owners");
292	        }
293	    }
294	
295	    /**
296	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
297	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
298	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
299	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
300	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
301	     * server's current date. Canonicalising the address here, before the household checks read it,
302	     * ensures duplicate detection and the shared household id both compare the normalized form.
303	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
304	     * duplicate, household and customer-code rules.
305	     *
306	     * @param owner the newly mapped owner to canonicalize
307	     */
308	    private void normalizeOwnerFields(Owner owner) {
309	        // Normalize the address on create so it is stored and returned in canonical form and every
310	        // later comparison (household duplicate detection and the shared household id) uses it.
311	        // A value that is blank after normalization is rejected with 400.
312	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
313	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
314	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
315	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
316	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
317	        // Store the (already syntactically validated) email lower-cased so it is persisted and
318	        // returned in canonical form. A missing email is left untouched.
319	        owner.setEmail(normalizeEmail(owner.getEmail()));
320	        // Validate the optional postcode against the fixed range for the city's region. A postcode
321	        // is checked only when present (it is optional); one out of range for the city's region is
322	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
323	        // value is left unchanged.
324	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
325	        // Reject a supplied registration date that is later than the server's current date with
326	        // 400, before any defaulting or business-day adjustment, so a future date is never
327	        // persisted regardless of how the roll-forward would move it.
328	        rejectFutureRegistrationDate(owner.getRegistrationDate());
329	        // Default the registration date to the server's current date when the client did not
330	        // supply one, then roll the effective date forward to a business day so a Saturday or
331	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
332	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
333	        // date-derived field (such as the membership number's year segment) and the per-day
334	        // create-limit are computed from.
335	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
336	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
337	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
338	    }
339	
340	    /**
341	     * Rejects a supplied registration date that is later than the server's current date with a
342	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
343	     * accepted, and a date on or before today is left for the normal defaulting and business-day
344	     * adjustment.
345	     *
346	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
347	     */
348	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
349	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
350	            throw new InvalidRegistrationDateException(
351	                "The supplied registration date " + registrationDate + " is later than the current date");
352	        }
353	    }
354	
355	    /**
356	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
357	     * following Monday, while a weekday is returned unchanged. Applied to the effective
358	     * registration date (whether supplied in the request or defaulted to the server date) so the
359	     * persisted registration date, every value derived from it and the per-day create-limit all
360	     * use the adjusted business day.
361	     *
362	     * @param date the effective registration date
363	     * @return the same date if it is a weekday, otherwise the following Monday
364	     */
365	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
366	        java.time.LocalDate adjusted = date;
367	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
368	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
369	            adjusted = adjusted.plusDays(1);
370	        }
371	        return adjusted;
372	    }
373	
374	    /**
375	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
376	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
377	     * syntactically valid address (rejecting anything else with 400).
378	     *
379	     * @param email the email value (may be {@code null})
380	     * @return the lower-cased email, or {@code null} if the input was {@code null}
381	     */
382	    private String normalizeEmail(String email) {
383	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
384	    }
385	
386	    /**
387	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
388	     * region derived from the owner's postcode (falling back to the city, via
389	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
390	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
391	     * 'NSW-A1B2C3D4'). The identity carries no sequence number, so it is a pure function of the
392	     * owner's region and identity fields.
393	     *
394	     * @param owner the owner being created, already normalized
395	     * @return the formatted customer code
396	     */
397	    private String customerCode(Owner owner) {
398	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
399	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
400	        return region + "-" + hash8;
401	    }
402	
403	    /**
404	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
405	     * fix the per-city sequence of an owner's customer code at creation time.
406	     *
407	     * @param city the city of the owner being created
408	     * @return the number of existing owners in a matching city
409	     */
410	    private int countOwnersInCity(String city) {
411	        return (int) this.clinicService.findAllOwners().stream()
412	            .filter(existing -> existing.getCity() != null
413	                && existing.getCity().equalsIgnoreCase(city))
414	            .count();
415	    }
416	
417	    /**
418	     * Counts the existing owners whose registration date is the given adjusted business day. Used
419	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
420	     * owners already carry that business day as their registration date.
421	     *
422	     * @param date the adjusted business-day registration date to match
423	     * @return the number of existing owners registered on that date
424	     */
425	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
426	        return (int) this.clinicService.findAllOwners().stream()
427	            .filter(existing -> date.equals(existing.getRegistrationDate()))
428	            .count();
429	    }
430	
431	    /**
432	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
433	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
434	     *
435	     * @param customerCode     the owner's customer code
436	     * @param registrationDate the owner's registration date
437	     * @return the formatted membership number
438	     */
439	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
440	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
441	    }
442	
443	    /**
444	     * Returns the existing owners who share the given household, i.e. have the same last name and
445	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
446	     * differing only in letter case or in incidental whitespace are treated as the same household.
447	     *
448	     * @param lastName the last name of the owner being created
449	     * @param address  the address of the owner being created
450	     * @return the existing owners with a matching last name and address (possibly empty)
451	     */
452	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
453	        String householdKey = householdNormalizer.householdKey(lastName, address);
454	        return this.clinicService.findAllOwners().stream()
455	            .filter(existing -> householdNormalizer
456	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
457	            .toList();
458	    }
459	
460	    /**
461	     * Counts the existing owners who share the given first and last name, compared
462	     * case-insensitively. Used to fix an owner's namesake count at creation time.
463	     *
464	     * @param firstName the first name of the owner being created
465	     * @param lastName  the last name of the owner being created
466	     * @return the number of existing owners with a matching first and last name
467	     */
468	    private int countNamesakes(String firstName, String lastName) {
469	        return (int) this.clinicService.findAllOwners().stream()
470	            .filter(existing -> existing.getFirstName() != null
471	                && existing.getFirstName().equalsIgnoreCase(firstName)
472	                && existing.getLastName() != null
473	                && existing.getLastName().equalsIgnoreCase(lastName))
474	            .count();
475	    }
476	
477	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
478	    @Override
479	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
480	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
481	        if (currentOwner == null) {
482	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
483	        }
484	        currentOwner.setAddress(ownerFieldsDto.getAddress());
485	        currentOwner.setCity(ownerFieldsDto.getCity());
486	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
487	        currentOwner.setLastName(ownerFieldsDto.getLastName());
488	        // Normalize the telephone to canonical E.164 form so it is stored and returned
489	        // consistently with create; an unformattable value is rejected with 400.
490	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
491	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
492	        this.clinicService.saveOwner(currentOwner);
493	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
494	    }
495	
496	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
497	    @Transactional
498	    @Override
499	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
500	        Owner owner = this.clinicService.findOwnerById(ownerId);
501	        if (owner == null) {
502	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
503	        }
504	        this.clinicService.deleteOwner(owner);
505	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
506	    }
507	
508	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
509	    @Override
510	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
511	        Owner owner = this.clinicService.findOwnerById(ownerId);
512	        if (owner == null) {
513	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
514	        }
515	        HttpHeaders headers = new HttpHeaders();
516	        Pet pet = petMapper.toPet(petFieldsDto);
517	        owner.setId(ownerId);
518	        pet.setOwner(owner);
519	        pet.getType().setName(null);
520	        this.clinicService.savePet(pet);
521	        PetDto petDto = petMapper.toPetDto(pet);
522	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
523	            .buildAndExpand(pet.getId()).toUri());
524	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
525	    }
526	
527	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
528	    @Override
529	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
530	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
531	        if (currentOwner != null) {
532	            Pet currentPet = this.clinicService.findPetById(petId);
533	            if (currentPet != null) {
534	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
535	                currentPet.setName(petFieldsDto.getName());
536	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
537	                this.clinicService.savePet(currentPet);
538	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
539	            }
540	        }
541	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
542	    }
543	
544	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
545	    @Override
546	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
547	        HttpHeaders headers = new HttpHeaders();
548	        Visit visit = visitMapper.toVisit(visitFieldsDto);
549	        Pet pet = new Pet();
550	        pet.setId(petId);
551	        visit.setPet(pet);
552	        this.clinicService.saveVisit(visit);
553	        VisitDto visitDto = visitMapper.toVisitDto(visit);
554	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
555	            .buildAndExpand(visit.getId()).toUri());
556	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
557	    }
558	
559	
560	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
561	    @Override
562	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
563	        Owner owner = this.clinicService.findOwnerById(ownerId);
564	        if (owner != null) {
565	            Pet pet = owner.getPet(petId);
566	            if (pet != null) {
567	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
568	            }
569	        }
570	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
571	    }
572	}
