28	            + "+ ((owner.getEmail() != null && !owner.getEmail().isBlank()) ? 1 : 0) "
29	            + "+ ((owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) ? 1 : 0)))")
30	    @Mapping(target = "locality",
31	        expression = "java(owner.getCustomerCode() != null "
32	            + "? owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-')) "
33	            + ": org.springframework.samples.petclinic.util.LocalityResolver.resolve(owner.getCity(), owner.getPostcode()))")
34	    @Mapping(target = "contactPreference",
35	        expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) "
36	            + "? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
37	    @Mapping(target = "checkDigit",
